<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Services\{CustomReportService,MalwareScanner};use Illuminate\Http\Request;use Illuminate\Support\Facades\{DB,Storage};use Illuminate\Validation\ValidationException;use Inertia\Inertia;
class ReportingAdministrationController extends Controller{
 public function index(){return Inertia::render('Admin/ReportingAdministration/Index',['sources'=>CustomReportService::SOURCES,'reports'=>DB::table('custom_reports')->latest()->get(),'schedules'=>DB::table('scheduled_reports')->latest()->get(),'exports'=>DB::table('report_exports')->latest('exported_at')->take(100)->get(),'imports'=>DB::table('import_batches')->latest()->take(100)->get(),'approvals'=>DB::table('workflow_approvals')->where('status','Pending')->latest()->take(100)->get(),'notifications'=>DB::table('communication_notifications')->latest()->take(100)->get(),'kpis'=>DB::table('kpi_targets')->latest()->get(),'activities'=>DB::table('administration_activities')->leftJoin('users','users.id','=','administration_activities.user_id')->select('administration_activities.*','users.name as user_name')->latest('occurred_at')->take(150)->get(),'campusComparison'=>$this->campusComparison()]);}
 public function report(Request$r){$d=$r->validate(['name'=>'required|string|max:255','data_source'=>'required|in:'.implode(',',array_keys(CustomReportService::SOURCES)),'columns'=>'required|array|min:1','columns.*'=>'string','filter_column'=>'nullable|string','filter_operator'=>'nullable|in:=,!=,>,>=,<,<=,like','filter_value'=>'nullable']);$allowed=CustomReportService::SOURCES[$d['data_source']]['columns'];if(array_diff($d['columns'],$allowed))throw ValidationException::withMessages(['columns'=>'One or more columns are not allowed.']);$filters=$d['filter_column']?[['column'=>$d['filter_column'],'operator'=>$d['filter_operator']?:'=','value'=>$d['filter_value']]]:[];$id=DB::table('custom_reports')->insertGetId(['campus_id'=>config('app.active_campus_id'),'name'=>$d['name'],'data_source'=>$d['data_source'],'columns'=>json_encode($d['columns']),'filters'=>json_encode($filters),'status'=>'active','created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);$this->activity($r,'report_created','custom_report',$id,"Created report {$d['name']}");return back()->with('success','Custom report saved.');}
 public function preview(int$report,CustomReportService$s){$r=DB::table('custom_reports')->where('campus_id',config('app.active_campus_id'))->find($report);abort_unless($r,404);return response()->json(['rows'=>$s->rows($r)->take(100)->values()]);}
 public function export(Request$r,int$report,CustomReportService$s){$definition=DB::table('custom_reports')->where('campus_id',config('app.active_campus_id'))->find($report);abort_unless($definition,404);$rows=$s->rows($definition);$csv=$s->csv($rows);$path='reports/exports/'.$report.'-'.now()->format('YmdHis').'.csv';Storage::disk('local')->put($path,$csv);$id=DB::table('report_exports')->insertGetId(['custom_report_id'=>$report,'campus_id'=>config('app.active_campus_id'),'format'=>'csv','file_path'=>$path,'row_count'=>$rows->count(),'status'=>'completed','exported_by'=>$r->user()->id,'exported_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);$this->activity($r,'report_exported','report_export',$id,"Exported {$definition->name} ({$rows->count()} rows)");return Storage::disk('local')->download($path,$definition->name.'.csv');}
 public function download(Request$r,int$export){$x=DB::table('report_exports')->where('campus_id',config('app.active_campus_id'))->find($export);abort_unless($x&&Storage::disk('local')->exists($x->file_path),404);return Storage::disk('local')->download($x->file_path);}
 public function schedule(Request$r){$d=$r->validate(['custom_report_id'=>'required|exists:custom_reports,id','frequency'=>'required|in:daily,weekly,monthly','recipients'=>'required|string','format'=>'required|in:csv','next_run_at'=>'required|date']);$id=DB::table('scheduled_reports')->insertGetId($d+['delivery_channel'=>'email','is_active'=>true,'created_at'=>now(),'updated_at'=>now()]);$this->activity($r,'report_scheduled','scheduled_report',$id,'Scheduled report delivery');return back()->with('success','Report delivery scheduled.');}
 public function import(Request$r,MalwareScanner$scanner){$d=$r->validate(['entity_type'=>'required|in:expenses','file'=>'required|file|mimes:csv,txt|max:5120']);$scanner->assertClean($r->file('file'));$handle=fopen($r->file('file')->getRealPath(),'r');$headers=array_map(fn($x)=>strtolower(trim($x)),fgetcsv($handle)?:[]);$required=['expense_head','amount','expense_date'];$errors=[];$valid=[];$line=1;while(($row=fgetcsv($handle))!==false){$line++;$data=array_combine($headers,array_pad($row,count($headers),null));if(!$data||!$data['expense_head']||!is_numeric($data['amount'])||!strtotime($data['expense_date'])){$errors[]="Row {$line}: expense_head, numeric amount and valid expense_date are required.";continue;}$valid[]=$data;}fclose($handle);$batch=DB::table('import_batches')->insertGetId(['campus_id'=>config('app.active_campus_id'),'entity_type'=>$d['entity_type'],'file_name'=>$r->file('file')->getClientOriginalName(),'status'=>$errors?'validated_with_errors':'validated','total_rows'=>count($valid)+count($errors),'valid_rows'=>count($valid),'invalid_rows'=>count($errors),'errors'=>json_encode($errors),'created_ids'=>json_encode([]),'imported_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);if($errors)return back()->with('warning','Validation completed with errors; nothing imported.');$ids=[];DB::transaction(function()use($valid,&$ids){foreach($valid as$x)$ids[]=DB::table('expenses')->insertGetId(['expense_head'=>$x['expense_head'],'amount'=>$x['amount'],'expense_date'=>date('Y-m-d',strtotime($x['expense_date'])),'description'=>$x['description']??null,'recorded_by'=>'Bulk import','created_at'=>now(),'updated_at'=>now()]);});DB::table('import_batches')->where('id',$batch)->update(['status'=>'completed','created_ids'=>json_encode($ids),'updated_at'=>now()]);$this->activity($r,'bulk_import','import_batch',$batch,'Imported '.count($ids).' expense records');return back()->with('success',count($ids).' records imported.');}
 public function rollback(Request$r,int$batch){$b=DB::table('import_batches')->where('campus_id',config('app.active_campus_id'))->where('id',$batch)->lockForUpdate()->first();abort_unless($b&&$b->status==='completed'&&!$b->rolled_back_at,422,'Batch cannot be rolled back.');$ids=json_decode($b->created_ids,true)?:[];DB::transaction(function()use($b,$ids){if($b->entity_type==='expenses')DB::table('expenses')->whereIn('id',$ids)->delete();DB::table('import_batches')->where('id',$b->id)->update(['status'=>'rolled_back','rolled_back_at'=>now(),'updated_at'=>now()]);});$this->activity($r,'import_rollback','import_batch',$batch,'Rolled back imported records');return back()->with('success','Import rolled back.');}
 public function kpi(Request$r){$d=$r->validate(['name'=>'required|string|max:255','metric'=>'required|in:student_count,fee_collection,attendance_rate,expense_total','target_value'=>'required|numeric|min:0','period'=>'required|in:monthly,quarterly,annual','starts_at'=>'required|date','ends_at'=>'required|date|after_or_equal:starts_at','owner_id'=>'nullable|exists:users,id']);$id=DB::table('kpi_targets')->insertGetId($d+['campus_id'=>config('app.active_campus_id'),'status'=>'active','created_at'=>now(),'updated_at'=>now()]);$this->activity($r,'kpi_created','kpi_target',$id,"Created KPI {$d['name']}");return back()->with('success','KPI target saved.');}
 private function campusComparison(){return DB::table('campuses')->where('is_active',true)->get()->map(function($c){return['id'=>$c->id,'name'=>$c->name,'students'=>DB::table('students')->where('campus_id',$c->id)->whereNull('deleted_at')->count(),'staff'=>DB::table('staff')->where('campus_id',$c->id)->whereNull('deleted_at')->count(),'collections'=>(float)DB::table('invoices')->where('campus_id',$c->id)->sum('paid_amount'),'outstanding'=>(float)DB::table('invoices')->where('campus_id',$c->id)->whereIn('status',['Unpaid','Partial'])->selectRaw('COALESCE(SUM(GREATEST(amount+fine-discount-paid_amount,0)),0) total')->value('total')];});}
 private function activity($r,$type,$subject,$id,$description){DB::table('administration_activities')->insert(['campus_id'=>config('app.active_campus_id'),'user_id'=>$r->user()->id,'type'=>$type,'subject_type'=>$subject,'subject_id'=>$id,'description'=>$description,'metadata'=>json_encode(['ip'=>$r->ip()]),'occurred_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);}
}
